public sealed record RuntimeWorldgroupIntegrationSmokeReport(bool Passed,IReadOnlyList<string> Checks){public string ToJson()=>JsonSerializer.Serialize(this,new JsonSerializerOptions{WriteIndented=true});public static RuntimeWorldgroupIntegrationSmokeReport Run(){var c=new List<string>();var s=new RuntimeWorldgroupIntegrationService([new("terminal-session",RuntimeIntegrationOwner.Worldgroup,true,new HashSet<string>(StringComparer.OrdinalIgnoreCase){"attach","detach"},true,true),new("module-character",RuntimeIntegrationOwner.MajorMud,true,new HashSet<string>(StringComparer.OrdinalIgnoreCase){"select"},false,true),new("host-message",RuntimeIntegrationOwner.Shared,true,new HashSet<string>(StringComparer.OrdinalIgnoreCase){"deliver"},true,true),new("unknown-native",RuntimeIntegrationOwner.UnknownNativeBoundary,false,new HashSet<string>{"invoke"},true,true)]);var ok=s.Authorize(new("terminal-session","attach","host",true,"acct","sess","c1"));if(!ok.Success||ok.Dispatch?.Owner!=RuntimeIntegrationOwner.Worldgroup)c.Add("worldgroup-dispatch");var denied=s.Authorize(new("terminal-session","attach","player",false,"acct","sess","c2"));if(denied.Success||!denied.Errors.Contains("host-authorization-required"))c.Add("host-auth");var module=s.Authorize(new("module-character","select","player",false,null,null,"c3"));if(!module.Success)c.Add("module-boundary");var unknown=s.Authorize(new("unknown-native","invoke","host",true,"acct","sess","c4"));if(unknown.Success)c.Add("unknown-fail-closed");c.AddRange(s.ValidateState());return new(c.Count==0,c);}}
